import {textEffectsTool} from './text-effects.mjs';
import {typeState,typeScale,typeCSS,typeTokens,fontFamily} from './experiments-core.mjs';
export function typographyTool({change}){const $=id=>document.getElementById('type-'+id);let state=typeState(),view='system',active=false;const effects=textEffectsTool({change});
 function workspace(){for(const kind of ['system','effect']){$(kind+'-preview').hidden=view!==(kind==='system'?'system':'effects');$(kind+'-controls').hidden=view!==(kind==='system'?'system':'effects')}$('view').value=view;effects.activate(active&&view==='effects')}
 $('view').onchange=e=>{view=e.target.value==='effects'?'effects':'system';workspace();change()};
 function draw(){const available=$('frame').parentElement?.clientWidth;if(available>0){const max=Math.max(1,Math.min(960,Math.floor(available)));$('width').max=max;$('width').min=Math.min(320,max);state.width=Math.min(state.width,max)}for(const key of Object.keys(state))if($(key))$(key).value=state[key];for(const key of ['base','ratio','leading','tracking','measure','width'])$(key+'-value').textContent=state[key]+(['base','width'].includes(key)?' px':key==='measure'?' ch':key==='tracking'?' em':'');const scale=typeScale(state),specimen=$('specimen');$('frame').style.width=state.width+'px';specimen.style.setProperty('--type-body',fontFamily(state.body));specimen.style.setProperty('--type-heading',fontFamily(state.heading));specimen.style.setProperty('--type-leading',state.leading);specimen.style.setProperty('--type-tracking',state.tracking+'em');specimen.style.setProperty('--type-measure',state.measure+'ch');for(const row of scale)specimen.style.setProperty('--type-'+(row.name==='body'?'body-size':row.name),row.css.replace('vw','cqi'));$('headline').textContent=state.title;$('copy').textContent=state.text;$('scale').replaceChildren();for(const r of [...scale].reverse()){const row=document.createElement('tr');for(const text of [r.name,r.min.toFixed(1)+'–'+r.max.toFixed(1)+' px']){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}$('scale').append(row)}change()}
 for(const key of Object.keys(state))if($(key))$(key).oninput=e=>{$('preset').value='';state=typeState({...state,[key]:e.target.value});draw()};
 $('preset').onchange=e=>{const presets={editorial:{heading:'serif',body:'dm',ratio:1.333,leading:1.75,tracking:-.025,measure:60},product:{heading:'manrope',body:'dm',ratio:1.2,leading:1.6,tracking:-.02,measure:64},compact:{heading:'system',body:'system',base:16,ratio:1.125,leading:1.5,tracking:0,measure:70}};if(presets[e.target.value]){state=typeState({...state,...presets[e.target.value]});draw()}};$('reset').onclick=()=>{state=typeState();$('preset').value='';draw()};draw();workspace();if(typeof ResizeObserver==='function')new ResizeObserver(()=>{if($('frame').parentElement?.clientWidth>0)draw()}).observe($('frame').parentElement);return {get:()=>({...state,view,effects:effects.get()}),set:s=>{if(s){state=typeState(s);view=s.view==='effects'?'effects':'system';effects.set(s.effects);draw();workspace()}},activate:v=>{active=v;workspace()},effects,css:()=>typeCSS(state),json:()=>JSON.stringify(typeTokens(state),null,2)}
}
